import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { crearCopiaSql } from '/private/tmp/avancecorp-f4-desarrollo/CRM-Avance-Corp/supabase/scripts/f4/copia-sql-local.mjs';
import { literal as q } from '/private/tmp/avancecorp-f4-desarrollo/CRM-Avance-Corp/supabase/scripts/f4/banco-local.mjs';
const copia=crearCopiaSql('cotitular_puerta');
const id=copia.sql("select id from public.contratos where numero_contrato='F4-BASE-INICIAL'");
const antes=copia.sql(`select count(*) from public.contrato_titulares where contrato_id=${q(id)}`);
const r=copia.sql(`begin;set local request.jwt.claims='{}';set local role anon;
 select public._sync_contrato_titulares(${q(id)},'[ {"nombre_completo":"COTITULAR FICTICIO SIN SESION","tipo_documento":"DNI","documento":"98765431"} ]');
 reset role;select jsonb_build_object('cotitularesTrasLlamada',(select count(*) from public.contrato_titulares where contrato_id=${q(id)}),
 'nombreCoincide',(select bool_and(nombre_completo='COTITULAR FICTICIO SIN SESION') from public.contrato_titulares where contrato_id=${q(id)}));rollback;`);
assert.equal(copia.sql(`select count(*) from public.contrato_titulares where contrato_id=${q(id)}`),antes);
const prueba={entorno:'copia SQL sintética',baseCopia:copia.nombre,contrato:id,resultado:JSON.parse(r),rollbackVerificado:true,
 funcion:'public._sync_contrato_titulares(uuid,jsonb)',md5:copia.sql("select md5(pg_get_functiondef('public._sync_contrato_titulares(uuid,jsonb)'::regprocedure))"),
 acl:copia.sql("select proacl from pg_proc where oid='public._sync_contrato_titulares(uuid,jsonb)'::regprocedure"),produccionModificada:false};
writeFileSync('/private/tmp/f4-cotitular-puerta-hallazgo.json',JSON.stringify(prueba,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify(prueba));
